"""Centralized display formatting for group chat.

All visual formatting, headers, and status message templates live here.
Design: clean Unicode, role-aware badges, compact and readable.
"""


def format_token_stats(prompt, completion, elapsed, cost, cache_tokens, reasoning_tokens):
    if reasoning_tokens > 0:
        visible = completion - reasoning_tokens
        completion_str = f'{visible:,}+💭{reasoning_tokens:,}'
    else:
        completion_str = f'{completion:,}'

    parts = [f'提示:{prompt:,} 回复:{completion_str}']

    if elapsed:
        parts.append(f'· {elapsed:.1f}s')
    if cost:
        parts.append(f'${cost:.4f}')
    if cache_tokens:
        parts.append(f'💾缓存:{cache_tokens:,}')

    return '`' + ' '.join(parts) + '`'


def _shorten_path(path, max_parts=2):
    if path and '/' in path:
        parts = path.split('/')
        return '/'.join(parts[-max_parts:]) if len(parts) > max_parts else path
    return path


def tool_result_brief(agent_name, tool_name, result):
    rlen = len(result) if result else 0

    if tool_name == 'web_search':
        import re
        m = re.search(r'\((\d+) results?\)', result[:100]) if result else None
        if m:
            count = int(m.group(1))
        elif result:
            count = max(result.count('\n'), 1)
        else:
            count = 0
        return f'    └ {count} results'

    if tool_name == 'web_fetch':
        return f'    └ fetched ({rlen:,}字)'

    if tool_name == 'exec':
        preview = (result or '').strip().replace('\n', ' ')[:55]
        return f'    └ {preview}…' if rlen > 55 else f'    └ {preview}'

    if tool_name in ('read_file',):
        return f'    └ 📄 ({rlen:,}字)'

    if tool_name in ('write_file', 'edit_file'):
        if result and result.strip().startswith('Error:'):
            return f'    └ ❌ {result.split(chr(10))[0][:60]}'
        return '    └ ✅ saved'

    if tool_name == 'list_dir':
        count = result.count('\n') if result else 0
        return f'    └ {count} entries'

    if tool_name == 'memory_palace':
        # FIX: check 'search' BEFORE 'stored' to avoid false positive
        # (search results contain "stored" as substring, e.g. "✅ stored")
        if result and 'search' in result.lower():
            return '    └ 🔍 found'
        if result and 'stored' in result:
            return '    └ ✅ stored'
        return f'    └ ({rlen:,}字)'

    if tool_name == 'manage_agent':
        return '    └ ✅ done'

    if tool_name == 'transfer_credits':
        return '    └ ✅ transferred'

    if tool_name == 'end_discussion':
        return '    └ 🏁 ended'

    return f'    └ ({rlen:,}字)'


def format_status_panel(agents, leader_name=None):
    lines = []
    max_name = max((len(a.get('name', '')) for a in agents), default=0)

    for agent in agents:
        name = agent.get('name', '?')
        status = agent.get('status', 'idle')
        emoji = '👑' if name == leader_name else '🟢' if status == 'active' else '⚪'
        badge = '▸' if name == leader_name else '·'

        label = name
        detail = None
        reason = agent.get('reason')

        if status == 'idle':
            label = name
        elif status == 'active':
            label = f'{name} · thinking'
        elif status == 'tool_call':
            tool = agent.get('tool', '?')
            label = f'{name} · {tool}'
        elif status == 'tool_result':
            tool = agent.get('tool', '?')
            brief = tool_result_brief(name, tool, agent.get('result', ''))
            label = f'{name} · {tool}'
            detail = brief
        elif status == 'error':
            label = f'{name} · error'
            detail = reason
        elif status == 'done':
            label = f'{name} · done'
        elif status == 'waiting':
            label = f'{name} · waiting'
        elif status == 'disabled':
            label = f'{name} · off'
        else:
            label = f'{name} · {status}'

        if reason and status not in ('error', 'tool_result'):
            activity = f'{label} ({(reason or "")[:30]})'
        elif detail:
            if not label.endswith('...'):
                activity = f'{label} {detail[:30]}'
            else:
                activity = f'{label[:-3]} {detail[:30]}...'
        else:
            activity = label

        name_pad = agent.ljust(max_name)
        lines.append(f'┃ {emoji} {badge} {name_pad}  {activity}')

    header = '┏━━ status ━━━━━━━━━━━━━━━━━━━┓'
    footer = '┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛'
    return '\n'.join([header] + lines + [footer])
